package org.apache.commons.math.fraction;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.ZeroException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.ArithmeticUtils;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BigFraction_floatValue_TriageGen2Test {

    private static final float EPSILON = 1e-7f;

    @Test
    public void testFloatValue_SimpleFraction() {
        // 1/2 = 0.5f
        BigFraction fraction = new BigFraction(1, 2);
        assertEquals(0.5f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_Integer() {
        // 5/1 = 5.0f
        BigFraction fraction = new BigFraction(5);
        assertEquals(5.0f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_Zero() {
        // 0/1 = 0.0f
        BigFraction fraction = new BigFraction(0, 1);
        assertEquals(0.0f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_Negative() {
        // -1/4 = -0.25f
        BigFraction fraction = new BigFraction(-1, 4);
        assertEquals(-0.25f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_NegativeNumerator() {
        // -3/2 = -1.5f
        BigFraction fraction = new BigFraction(-3, 2);
        assertEquals(-1.5f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_NegativeDenominator() {
        // 3/-2 = -1.5f
        BigFraction fraction = new BigFraction(3, -2);
        assertEquals(-1.5f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_BothNegative() {
        // -1/-2 = 0.5f
        BigFraction fraction = new BigFraction(-1, -2);
        assertEquals(0.5f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_LargeValues() {
        // Testing values that fit in float but are large BigIntegers
        BigInteger num = new BigInteger("100000000");
        BigInteger den = new BigInteger("1");
        BigFraction fraction = new BigFraction(num, den);
        assertEquals(100000000.0f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_PrecisionLoss() {
        // BigFraction can hold much more precision than float. 
        // 1/3 is 0.333...
        BigFraction fraction = new BigFraction(1, 3);
        assertEquals(0.33333334f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_Infinity() {
        // In BigFraction, division by zero is generally not allowed in constructor,
        // but if the numerator is very large and denominator is very small (not zero),
        // it might result in Infinity.
        // However, BigFraction constructor validates denominator != 0.
        // We test a very large number.
        BigInteger hugeNum = new BigInteger("1" + "0".repeat(40)); 
        BigFraction fraction = new BigFraction(hugeNum, 1);
        // Float.POSITIVE_INFINITY or a very large float
        float val = fraction.floatValue();
        assertEquals(Float.POSITIVE_INFINITY, val, 0.0f);
    }

    @Test
    public void testFloatValue_VerySmallValue() {
        // 1 / 10^40 should result in 0.0f due to float underflow
        BigInteger num = BigInteger.ONE;
        BigInteger den = BigInteger.TEN.pow(40);
        BigFraction fraction = new BigFraction(num, den);
        assertEquals(0.0f, fraction.floatValue(), 0.0f);
    }
}
